{
  "summary": "总体维持保守框架：QQQ维持0仓位防御逻辑，SOXX维持偏空上限不变，但均把“财报-量能-波动联动缺失/隔夜跳空数据缺失”作为必须复评触发条件。VIX仅作为宏观风险环境信号（context-only）用于强化两者的风险约束触发逻辑。",
  "confidence": 0.0,
  "authoritative_fields": {
    "stance": "conservative",
    "unique_risk_contribution": "QQQ面临政策口径未闭环、流动性托底不确定与隔夜跳空数据缺失导致风险边界不可量化；SOXX除宏观与估值偏空外，还受行业事件窗口和财报-量能-波动联动不充分导致的方向反转不确定性影响更高。",
    "disagreement_with_prior": "与Phase 3/4方向一致（QQQ Hold、SOXX Underweight/偏空候选），无方向性冲突；新增约束仅为将缺失的隔夜跳空与1-5日事件-价格响应链条设为高优先级硬化监控条件。",
    "no_new_information": true,
    "recommended_adjustment": "保留QQQ执行上限0.0与SOXX上限0.30不变，补齐并挂钩缺失数据（隔夜跳空、1-5日分钟级事件-价格响应）后再决定是否调整；强化风险触发条件为VIX/利率共振与财报窗口的量价一致性检验。",
    "per_asset": {
      "QQQ": {
        "position_cap_pct": 0.0,
        "max_drawdown_pct": null,
        "stop_type": "none",
        "risk_off_trigger": "任一触发：1) 政策口径继续偏鹰且无有效流动性托底确认；2) VIX与利率预期快速共振抬升且QQQ出现快速放量下跌；3) 出现不可覆盖的负向财报/宏观共振。触发后处理：维持0持仓、暂停新增、提高现金缓冲。",
        "rebalance_trigger": "美联储政策口径出现可验证鸽化；QQQ在政策与财报窗口出现持续放量且方向一致的价格重定价；关键缺口数据（隔夜跳空与1-5日分钟级反应）补齐。",
        "review_window": "以每次关键政策与财报窗口后的事件-价格联动为复评节点，并在缺口与1-5日分钟级链路补齐时追加复评。",
        "constraint_confidence": 0.0
      },
      "SOXX": {
        "position_cap_pct": 0.3,
        "max_drawdown_pct": null,
        "stop_type": "none",
        "risk_off_trigger": "任一触发：1) 周内财报未改善现金流/库存/毛利且SOXX成交弱于放量偏空；2) 宏观利率预期上移且风险偏好回落（VIX伴随抬升）；3) 财报窗口后SOXX方向性下跌被放大。处理：继续偏空框架并不突破0.30，等待更清晰反转证据后再降杠杆。",
        "rebalance_trigger": "SOXX财报放量且同步验证现金流/库存/毛利改善；宏观出现明确放松并伴随风险拥抱；事件窗口缺口（成交/量能/波动）链路补齐。",
        "review_window": "以周内财报窗口及后续关键事件窗口为复评周期，结合事件-量能-波动联动缺失补齐进度。",
        "constraint_confidence": 0.0
      }
    },
    "cash_hedge_recommendation": "提高现金对冲/流动性缓冲作为第一道防线，用于事件驱动下快速降杠杆与防止执行失效；不要求固定比例固定对冲单。",
    "portfolio_risk_triggers": [
      "VIX上行与利率预期抬升共振放大两只可投资资产的回撤压力（contextual）",
      "政策口径转向偏鹰且无流动性托底确认时，优先压缩净新进并维持现金缓冲",
      "财报窗口出现负向共振且量能放大，但缺乏1-5日分钟级价格-成交响应量化时不提前扩大偏空规模"
    ]
  },
  "details": [
    {
      "asset": "QQQ",
      "note": "已明确将仓位执行上限保持0.00（无新增），并强调无法因缺失隔夜跳空与1-5日分钟级响应数据设置硬性回撤/跳空控制参数。"
    },
    {
      "asset": "SOXX",
      "note": "已明确维持0.30上限（沿用0.3），并要求“财报-量能-波动”联动闭环作为偏空执行前置条件。"
    },
    {
      "asset": "VIX",
      "note": "VIX被明确限定为context-only的风险环境信号，不形成独立交易对象，仅用于传导：VIX上行放大QQQ和SOXX的风险暴露。"
    },
    {
      "evidence_scope": "indirect/contextual",
      "note": "两者共因共享于利率路径与流动性预期；SOXX因半导体风险偏好弹性对放大后的波动更敏感，但风险共振与个股/行业事件仍为主导传导链。"
    }
  ],
  "missing_fields": [
    "QQQ.max_drawdown_pct",
    "SOXX.max_drawdown_pct"
  ],
  "ambiguities": []
}
